function twoSum(counts: number[], target: number) {
  const seen = new Map<number, number>(); // value → index
  for (let i = 0; i < counts.length; i++) {
    const need = target - counts[i];
    if (seen.has(need)) return [seen.get(need)!, i];
    seen.set(counts[i], i);
  }
  return null; // say this case out loud too
}
